parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "niche": {
      "type": "string",
      "description": "Business type as typed into a directory search box, e.g. 'hvac contractors'"
    },
    "city": {
      "type": "string",
      "description": "US city name only, no state"
    },
    "state": {
      "type": "string",
      "description": "US state, spelled out in full, e.g. 'Texas'"
    },
    "reason": {
      "type": "string",
      "description": "One sentence on why this segment should out-perform"
    }
  },
  "required": [
    "niche",
    "city",
    "state"
  ]
}

parameters.jsCode:
// The segment picker chooses where to look; this node is the only place the
// URL grammar and the goal wording live. Both are fixed text with three slots,
// so a differently-worded model response can never rename an extracted column.
const COLUMNS = 'business_name, address, phone, website, listing_url';

// One page of 200 is one page of credits. Manta honours page_size well past
// its own UI default, so widening the page is cheaper than raising Max Pages.
const PAGE_SIZE = 200;

// A chain LLM with an output parser returns the parsed object under `output`.
const raw = $input.first().json;
const pick = raw.output ?? raw;

const niche = String(pick.niche ?? '').trim();
const city = String(pick.city ?? '').trim();
const state = String(pick.state ?? '').trim();

// Fail loudly here rather than minting a job against a malformed URL: a job is
// charged on creation, so a bad segment costs real money before it returns.
if (!niche || !city || !state) {
  throw new Error(`Segment picker returned an incomplete segment: ${JSON.stringify(pick)}`);
}

// Hand-encoded: URLSearchParams is not exposed in the task-runner sandbox, and
// city names carry spaces, so the escaping cannot be skipped.
const query = [
  ['search', niche],
  ['country', 'United States'],
  ['state', state],
  ['city', city],
  ['page_size', String(PAGE_SIZE)],
]
  .map(([key, value]) => `${key}=${encodeURIComponent(value)}`)
  .join('&');

return [
  {
    json: {
      niche,
      city,
      state,
      search_url: `https://www.manta.com/search?${query}`,
      goal: `I'm looking for ${niche} in ${city}, ${state}. Extract ${COLUMNS}.`,
    },
  },
];

// The fetch and the scoring share one node because they cannot be separated
// without losing the lead. An HTTP Request node replaces the item with the
// response, and these rows carry the only copy of the phone number — the field
// the whole list exists for.
//
// Every request here is expected to fail some of the time. A domain that no
// longer resolves is the strongest finding this workflow produces, not an
// error, so failures are caught per lead and scored rather than thrown.

const CONCURRENCY = 8;
const TIMEOUT_MS = 12000;
const UA = 'Mozilla/5.0 (compatible; n8n-lead-qualifier)';

// A page that arrives as a script bundle tells us nothing: absent markup is
// absent evidence, not a defect. Below this many words of visible text the
// site is judged unreadable rather than broken.
const MIN_VISIBLE_WORDS = 120;

const BOOKING = /calendly|opentable|resy\.com|booksy|squareup|square\.site|toasttab|chownow|doordash|ubereats|grubhub|acuityscheduling|setmore|schedulicity|mindbody|sevenrooms/i;
const ANALYTICS = /google-analytics\.com|googletagmanager|gtag\(|G-[A-Z0-9]{8,}|UA-\d{4,}/i;
const DEPRECATED = /<font\b|<center\b|<marquee\b|bgcolor=|<frameset/i;
const PARKED = /domain (is )?(for sale|parked)|sedoparking|hugedomains|buy this domain/i;

// Weighted by what a prospect will pay to fix, not by how old the markup looks.
// A missing booking or contact path outranks legacy HTML because it is the
// thing the business already knows it is losing money on.
const RULES = [
  ['no online booking or ordering', 3, (s) => !s.booking],
  ['no contact form', 3, (s) => !s.form],
  ['outdated CMS', 3, (s) => s.oldCms],
  ['no analytics', 2, (s) => !s.analytics],
  ['plain HTTP only', 2, (s) => !s.https],
  ['no schema.org markup', 1, (s) => !s.schema],
  ['no OpenGraph tags', 1, (s) => !s.og],
  ['dated jQuery', 1, (s) => s.oldJquery],
  ['deprecated HTML tags', 1, (s) => s.deprecated],
  ['no favicon', 1, (s) => !s.favicon],
];

const HOT_AT = 7;
const WARM_AT = 4;

const leads = $input.all().map((item) => item.json);

// Parsed by regex rather than URL(): the sandbox does not expose the whole
// WHATWG URL surface, and a listing's website field is often missing a scheme.
const hostOf = (url) => {
  const match = String(url ?? '').match(/^https?:\/\/([^/?#]+)/i);
  return match ? match[1].replace(/^www\./, '').toLowerCase() : '';
};

// A domain appearing more than once in one sweep is a chain or a duplicate
// listing. Neither can buy anything: the branch manager does not choose the
// website. Frequency catches them without a brand list anyone has to maintain.
const frequency = {};
for (const lead of leads) {
  const host = hostOf(lead.website);
  if (host) frequency[host] = (frequency[host] || 0) + 1;
}

// Arrow function so `this` stays bound: the bare $helpers global does not exist
// in the task runner, and this.helpers is the only way out to the network.
const fetchOnce = async (url) => {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url,
    timeout: TIMEOUT_MS,
    headers: { 'User-Agent': UA },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  return {
    status: Number(response.statusCode) || 0,
    body: typeof response.body === 'string' ? response.body : String(response.body ?? ''),
  };
};

// HTTPS is measured by asking for it, not by reading the response: the helper
// does not report the URL it ended on, so a site that redirects http to https
// would otherwise be accused of serving plain HTTP. Reaching port 443 at all
// counts, including a 404 there — the certificate is what is being tested.
const inspect = async (website) => {
  const host = hostOf(website);
  if (!host) return { ...(await fetchOnce(website)), https: /^https:/i.test(website) };
  try {
    return { ...(await fetchOnce(`https://${host}`)), https: true };
  } catch {
    return { ...(await fetchOnce(`http://${host}`)), https: false };
  }
};

const readSignals = (body, https) => {
  const low = body.toLowerCase();
  const text = body
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ');
  const words = (text.match(/\w+/g) || []).length;
  const wpVersion = (low.match(/wp-(?:includes|content)[^"']*[?&]ver=(\d+)\./) || [])[1];
  return {
    words,
    https,
    booking: BOOKING.test(body),
    form: low.includes('<form') || low.includes('mailto:'),
    analytics: ANALYTICS.test(body),
    schema: low.includes('application/ld+json') || low.includes('itemtype='),
    og: low.includes('og:title') || low.includes('property="og:'),
    favicon: /rel=["']?(shortcut )?icon/i.test(body),
    deprecated: DEPRECATED.test(body),
    oldJquery: /jquery[/-][12]\./i.test(low),
    oldCms: wpVersion ? Number(wpVersion) <= 5 : false,
    parked: PARKED.test(body),
  };
};

const qualify = async (lead) => {
  const base = {
    listing_url: String(lead.listing_url ?? ''),
    business_name: String(lead.business_name ?? ''),
    address: String(lead.address ?? ''),
    phone: String(lead.phone ?? ''),
    website: String(lead.website ?? ''),
  };
  const host = hostOf(base.website);

  if (host && frequency[host] > 1) {
    return { ...base, tier: 'skip', score: 0, site_status: 'chain', defects: '' };
  }

  // No website at all is the cleanest finding in the set and needs no fetch:
  // a business reachable only by phone has nothing to audit.
  if (!base.website) {
    return {
      ...base,
      tier: 'hot',
      score: 10,
      site_status: 'none',
      defects: 'no website at all',
    };
  }

  let probe;
  try {
    probe = await inspect(base.website);
  } catch (error) {
    // Thrown here means DNS failure, refused connection or timeout — the
    // listed address does not answer, which is the most urgent pitch available.
    return {
      ...base,
      tier: 'hot',
      score: 10,
      site_status: 'dead',
      defects: `site unreachable (${String(error.message || error).slice(0, 80)})`,
    };
  }

  if (probe.status === 0 || probe.status >= 400) {
    return {
      ...base,
      tier: probe.status === 403 || probe.status === 401 ? 'skip' : 'hot',
      score: probe.status === 403 || probe.status === 401 ? 0 : 9,
      site_status: probe.status === 403 || probe.status === 401 ? 'blocked' : `http ${probe.status}`,
      defects: `site returns HTTP ${probe.status}`,
    };
  }

  const signals = readSignals(probe.body, probe.https);

  if (signals.parked) {
    return { ...base, tier: 'hot', score: 9, site_status: 'parked', defects: 'domain parked or for sale' };
  }

  // Scoring a script bundle would flag every capability as missing and produce
  // a confident, wrong pitch. Say so instead.
  if (signals.words < MIN_VISIBLE_WORDS) {
    return { ...base, tier: 'unknown', score: 0, site_status: 'js-rendered', defects: '' };
  }

  const hits = RULES.filter(([, , test]) => test(signals));
  const score = hits.reduce((sum, [, weight]) => sum + weight, 0);
  return {
    ...base,
    score,
    tier: score >= HOT_AT ? 'hot' : score >= WARM_AT ? 'warm' : 'healthy',
    site_status: 'live',
    defects: hits.map(([label]) => label).join('; '),
  };
};

// A bounded pool rather than Promise.all: a few hundred simultaneous sockets
// from one execution is what gets an n8n instance rate-limited by its host.
const results = new Array(leads.length);
let cursor = 0;
const worker = async () => {
  while (cursor < leads.length) {
    const index = cursor++;
    results[index] = await qualify(leads[index]);
  }
};
await Promise.all(Array.from({ length: Math.min(CONCURRENCY, leads.length) }, worker));

return results.map((json, index) => ({ json, pairedItem: { item: index } }));

// Collapses the sweep into one item: the brief, plus the counts the segment
// picker reads back next week. Ranking happens here rather than in the scorer
// so the scorer stays a pure per-lead judgement.

const SHOW = 25;

const rows = $input.all().map((item) => item.json);
const segment = $('Build the Search URL').first().json;

const rank = { hot: 0, warm: 1, healthy: 2, unknown: 3, skip: 4 };
const worth = rows
  .filter((row) => row.tier === 'hot' || row.tier === 'warm')
  .sort((a, b) => rank[a.tier] - rank[b.tier] || b.score - a.score);

const count = (tier) => rows.filter((row) => row.tier === tier).length;

const line = (row) => {
  const reason = row.defects || row.site_status;
  return `- **${row.business_name}** — ${row.phone || 'no phone'} — ${reason}\n  ${row.address}${row.website ? `\n  ${row.website}` : ''}`;
};

const brief = [
  `# ${segment.niche} in ${segment.city}, ${segment.state}`,
  '',
  `${rows.length} businesses swept — ${count('hot')} hot, ${count('warm')} warm, ${count('healthy')} healthy, ${count('unknown')} unreadable, ${count('skip')} skipped.`,
  '',
  ...(worth.length ? worth.slice(0, SHOW).map(line) : ['Nothing qualified in this segment.']),
  ...(worth.length > SHOW ? ['', `_${worth.length - SHOW} more in the table._`] : []),
].join('\n');

return [
  {
    json: {
      niche: segment.niche,
      city: segment.city,
      state: segment.state,
      search_url: segment.search_url,
      leads_found: rows.length,
      tier_a_count: count('hot'),
      brief,
    },
  },
];
